import { setupRerender, act } from 'preact/test-utils';
import { createElement, render } from 'preact';
import { useState } from 'preact/hooks';
import { setupScratch, teardown } from '../../../test/_util/helpers';

/** @jsx createElement */

// Temporary reproduction for preactjs/preact#3739 -- NOT part of the repo test suite.
describe('TEMP #3739', () => {
	/** @type {HTMLDivElement} */
	let scratch;

	/** @type {() => void} */
	let rerender;

	beforeEach(() => {
		scratch = setupScratch();
		rerender = setupRerender();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('updates child when props change and child state was set+unset in the same tick', () => {
		let setChildActive, updateParent;

		function Child(props) {
			const [active, setActive] = useState(false);
			setChildActive = v => {
				setActive(true);
				setActive(false);
			};
			return <p>{props.text}</p>;
		}

		function Parent() {
			const [value, setValue] = useState('initial');
			updateParent = v => setValue(v);
			return <Child text={value} />;
		}

		render(<Parent />, scratch);
		expect(scratch.innerHTML).to.equal('<p>initial</p>');

		// Child state set + undone, parent prop updated, all in one tick
		setChildActive();
		updateParent('updated');
		rerender();

		expect(scratch.innerHTML).to.equal('<p>updated</p>');

		// A second parent-only update should keep working
		updateParent('again');
		rerender();
		expect(scratch.innerHTML).to.equal('<p>again</p>');
	});

	it('still updates when child state net-changes and parent updates in same tick', () => {
		let setChild, updateParent;

		function Child(props) {
			const [active, setActive] = useState(false);
			setChild = v => setActive(v);
			return <p>{props.text}</p>;
		}

		function Parent() {
			const [value, setValue] = useState('initial');
			updateParent = v => setValue(v);
			return <Child text={value} />;
		}

		render(<Parent />, scratch);

		setChild(true);
		updateParent('updated');
		rerender();
		expect(scratch.innerHTML).to.equal('<p>updated</p>');
	});
});
